package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.MathRuntimeException;
import org.apache.commons.math.special.Erf;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for NormalDistributionImpl#inverseCumulativeProbability
 */
public class NormalDistributionImpl_inverseCumulativeProbability_TriageGen2Test {

    private NormalDistributionImpl distribution;
    private static final double DELTA = 1e-10;

    @Before
    public void setUp() {
        // Standard normal distribution (mean = 0, sd = 1)
        distribution = new NormalDistributionImpl(0, 1);
    }

    @Test
    public void testInverseCumulativeProbability_P0() throws Exception {
        // Tests the branch: if (p == 0)
        double result = distribution.inverseCumulativeProbability(0.0);
        assertEquals(Double.NEGATIVE_INFINITY, result, 0.0);
    }

    @Test
    public void testInverseCumulativeProbability_P1() throws Exception {
        // Tests the branch: if (p == 1)
        double result = distribution.inverseCumulativeProbability(1.0);
        assertEquals(Double.POSITIVE_INFINITY, result, 0.0);
    }

    @Test
    public void testInverseCumulativeProbability_StandardValues() throws Exception {
        // Tests the branch: return super.inverseCumulativeProbability(p)
        // For a standard normal distribution, p=0.5 should return mean (0)
        assertEquals(0.0, distribution.inverseCumulativeProbability(0.5), DELTA);

        // Testing common Z-score values
        // p approx 0.8413 -> z approx 1.0
        assertEquals(1.0, distribution.inverseCumulativeProbability(0.8413447460685429), 1e-7);
        // p approx 0.1587 -> z approx -1.0
        assertEquals(-1.0, distribution.inverseCumulativeProbability(0.1586552539314571), 1e-7);
    }

    @Test
    public void testInverseCumulativeProbability_CustomMeanAndSD() throws Exception {
        // Tests with non-standard parameters
        NormalDistributionImpl customDist = new NormalDistributionImpl(10.0, 2.0);
        // p=0.5 should return the mean (10.0)
        assertEquals(10.0, customDist.inverseCumulativeProbability(0.5), DELTA);
        // p=0.8413... should return mean + 1*sd = 12.0
        assertEquals(12.0, customDist.inverseCumulativeProbability(0.8413447460685429), 1e-7);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testInverseCumulativeProbability_PLessThanZero() throws Exception {
        // Testing behavior for invalid input (p < 0)
        // The super implementation typically throws MathIllegalArgumentException for p outside [0, 1]
        distribution.inverseCumulativeProbability(-0.1);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testInverseCumulativeProbability_PGreaterThanOne() throws Exception {
        // Testing behavior for invalid input (p > 1)
        distribution.inverseCumulativeProbability(1.1);
    }
}
